import childProcess from 'node:child_process';
import { syncBuiltinESMExports } from 'node:module';
import { subscribe } from 'node:diagnostics_channel';

let active = false;
let start = 0;
let samples = [];
let httpStart = 0;
let httpEnd = 0;
let requestSeen = 0;
const original = childProcess.execFile;

childProcess.execFile = function (...args) {
    if (!active || args[0] !== 'git') return original.apply(this, args);
    const sample = { command: args[1][2], begin: performance.now() - start };
    const index = args.length - 1;
    const callback = args[index];
    args[index] = function (...values) {
        sample.callback = performance.now() - start;
        sample.failed = values[0] !== null;
        return callback.apply(this, values);
    };
    samples.push(sample);
    const child = original.apply(this, args);
    sample.returned = performance.now() - start;
    child.once('spawn', () => { sample.spawned = performance.now() - start; });
    child.once('exit', () => { sample.exited = performance.now() - start; });
    child.once('close', () => { sample.closed = performance.now() - start; });
    return child;
};
syncBuiltinESMExports();
subscribe('http.server.request.start', ({ request }) => {
    if (active && request.url.endsWith('/branches')) {
        requestSeen++;
        httpStart = performance.now() - start;
    }
});
subscribe('http.server.response.finish', ({ request }) => {
    if (active && request.url.endsWith('/branches')) httpEnd = performance.now() - start;
});
export function beginGitProbe() {
    start = performance.now();
    active = true;
    samples = [];
    httpStart = httpEnd = requestSeen = 0;
}
export function endGitProbe() {
    active = false;
    const total = performance.now() - start;
    if (samples.length !== 2 || requestSeen !== 1 || samples.some(s => s.failed)) {
        throw new Error('Expected exactly one branches HTTP request and its two successful Git children');
    }
    const last = Math.max(...samples.map(s => s.callback));
    const metrics = {
        probeHttpArrivalMs: httpStart,
        probeHttpServerMs: httpEnd - httpStart,
        probeAfterGitServerMs: httpEnd - last,
        probeHttpReadbackMs: total - httpEnd,
    };
    for (const row of samples) {
        const name = row.command === 'status' ? 'Status' : 'Refs';
        metrics[`probe${name}StartMs`] = row.begin;
        metrics[`probe${name}SpawnCallMs`] = row.returned - row.begin;
        metrics[`probe${name}ToSpawnMs`] = row.spawned - row.begin;
        metrics[`probe${name}SpawnToExitMs`] = row.exited - row.spawned;
        metrics[`probe${name}ExitToCallbackMs`] = row.callback - row.exited;
        metrics[`probe${name}TotalMs`] = row.callback - row.begin;
    }
    return metrics;
}

