import childProcess from 'node:child_process';
import { syncBuiltinESMExports } from 'node:module';
import { mkdirSync, mkdtempSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';

const repo='/private/tmp/rotom-model-switch-climb';
const { WORKLOAD }=await import(repo+'/test/perf/workload.ts');
const fixture=mkdtempSync(join(tmpdir(),'rt-git-launch-diagnostic-'));
const workspace=join(fixture,'project');
mkdirSync(join(workspace,'src'),{recursive:true});
writeFileSync(join(workspace,'AGENTS.md'),'Benchmark project.\n');
for(let i=0;i<WORKLOAD.changedFiles;i++)writeFileSync(join(workspace,'src',`file-${i}.txt`),`line ${i}\n`.repeat(50));
const setup=(...args)=>childProcess.execFileSync('git',['-C',workspace,...args],{stdio:'ignore'});
setup('init','-q','-b','main');
setup('add','-A');
setup('-c','user.name=perf','-c','user.email=perf@example.invalid','-c','core.hooksPath=/dev/null','commit','-q','-m','seed');
setup('branch','feature');
for(let i=0;i<WORKLOAD.changedFiles;i++)writeFileSync(join(workspace,'src',`file-${i}.txt`),`changed ${i}\n`.repeat(60));

const original=childProcess.execFile;
const direct=childProcess.execFileSync('/usr/bin/xcrun',['--find','git'],{encoding:'utf8'}).trim();
let executable='git';
let calls=[];
let serial=0;
childProcess.execFile=function(file,args,options,callback){
    assert.equal(file,'git');
    const trace=`/tmp/round2-git-native-${++serial}.jsonl`;
    const sample={command:args[2],trace,started:performance.now()};
    calls.push(sample);
    const child=original(executable,args,{...options,env:{...options.env,GIT_TRACE2_EVENT:trace}},(error,...rest)=>{
        sample.callback=performance.now();
        return callback(error,...rest);
    });
    sample.returned=performance.now();
    child.once('spawn',()=>{sample.spawned=performance.now();});
    child.once('exit',()=>{sample.exited=performance.now();});
    return child;
};
syncBuiltinESMExports();
const { branchesIn }=await import(repo+'/src/server/branches.ts');
const runs=[];
try{
for(const label of ['shim','developer','developer','shim','shim','developer']){
    executable=label==='shim'?'git':direct;
    calls=[];
    const start=performance.now();
    const result=await branchesIn(workspace);
    const total=performance.now()-start;
    assert.equal(result.changed,WORKLOAD.changedFiles);
    assert.equal(result.local.length,2);
    assert.equal(result.head.branch,'main');
    assert.equal(calls.length,2);
    const samples=calls.map(row=>{
        const events=readFileSync(row.trace,'utf8').trim().split('\n').map(line=>JSON.parse(line));
        const exit=events.find(event=>event.event==='exit');
        assert.equal(exit.code,0);
        const nativeMs=Number(exit.t_abs)*1000;
        return {command:row.command,wallMs:row.callback-row.started,spawnToExitMs:row.exited-row.spawned,spawnCallMs:row.returned-row.started,nativeMs,outsideNativeMs:row.callback-row.started-nativeMs,events:events.length,trace:row.trace};
    });
    runs.push({label,executable,totalMs:total,calls:samples});
}
writeFileSync('/tmp/round2-git-native-summary.json',JSON.stringify({schema:1,node:process.version,git:childProcess.execFileSync(direct,['--version'],{encoding:'utf8'}).trim(),changedFiles:WORKLOAD.changedFiles,direct,runs},null,2));
console.log(JSON.stringify(runs.map(r=>({label:r.label,totalMs:r.totalMs,calls:r.calls})),null,2));
}finally{rmSync(fixture,{recursive:true,force:true});}

